export default pattern<RingLoopsFrameInput, RingLoopsFrameOutput>(({
  input,
  output,
}) => {
  const state = new Writable<IframeStateData>(DEFAULT_STATE);
  const iframeInput = input ?? DEFAULT_INPUT;
  const context = IframeContext({
    input: iframeInput,
    state,
    output,
    ["jam"]: state,
  });

  return {
    [NAME]: "Ring Loops",
    [UI]: (
      <div style={{ width: "100%", height: "100vh" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
            ["jam"]: "presence",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
